import {
  AUTH_HTTP_ERROR,
  AUTH_SESSION_ERROR,
  AUTH_COOKIE_ERROR
} from '../actions/authActions';

const initialState = {
  authErrorMessage: null,
  errorAlertText: null,
  showErrorAlert: false
};

export default function authReducer(state = initialState, action) {
  switch(action.type) {

    case AUTH_HTTP_ERROR:
       //console.log(action.authHttpError)
      // All done: set loading "false".
      // Also, replace the items with the ones from the server
      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "Something went wrong. Please try again later.",
        showErrorAlert: true   
      };

      
    case AUTH_SESSION_ERROR:
       //console.log(action.authHttpError)
      // All done: set loading "false".
      // Also, replace the items with the ones from the server
      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "Something went wrong. Please try again later.",
        showErrorAlert: true
      };
      
    case AUTH_COOKIE_ERROR:
       //console.log(action.authHttpError)
      // All done: set loading "false".
      // Also, replace the items with the ones from the server
      return {
        ...state,
        authErrorMessage: action.error,
        errorAlertText: "Something went wrong. Please try again later.",
        showErrorAlert: true
      };
      
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
